public interface AtmState {
    void insertCard(ATM atm, Card card);
    void enterPin(ATM atm, int pin);
    void requestTransaction(ATM atm, TransactionType type);
    void dispenseCash(ATM atm, double amount);
    void ejectCard(ATM atm);
}

public class AuthenticatedState implements AtmState {
    @Override
    public void requestTransaction(ATM atm, TransactionType type) {
        System.out.println("Transaction selected: " + type);
        atm.setCurrentState(atm.getTransactionState());
    }
    // Other state methods throw IllegalStateException or handle accordingly
}
